use base64::{Engine as _, engine::general_purpose::STANDARD};

// Tiny deterministic 440 Hz/8 kHz fixtures generated from a synthetic signal with FFmpeg 8.1.2.
// They exercise the selected Symphonia codec/container families without storing opaque binaries.
const FLAC: &str = r"";
const MP3: &str = r"";
const M4A: &str = r"";
const OGG: &str = r"";
const WEBM: &str = r"";

const AIFF: &str = r"";
const CAF: &str = r"";

pub fn encoded_fixture(extension: &str) -> Vec<u8> {
    let encoded = match extension {
        "aif" | "aiff" | "aifc" => AIFF,
        "caf" => CAF,
        "flac" => FLAC,
        "mp3" => MP3,
        "m4a" | "mp4" => M4A,
        "ogg" | "oga" => OGG,
        "mka" | "mkv" | "webm" => WEBM,
        _ => panic!("no encoded fixture for extension {extension}"),
    };
    STANDARD.decode(encoded).unwrap()
}
